function escapeHtml(s) {
	return s.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;").replaceAll("\"", "&quot;");
}
function tableHtml(headers, rows) {
	if (!headers.length) return "";
	return `<table><thead><tr>${headers.map((h) => `<th>${escapeHtml(h)}</th>`).join("")}</tr></thead><tbody>${rows.map((r) => `<tr>${r.map((c) => `<td>${escapeHtml(c ?? "")}</td>`).join("")}</tr>`).join("")}</tbody></table>`;
}
async function gallerySrc(item) {
	try {
		if (item.src?.startsWith("data:")) return item.src;
		if (item.mediaKey) {
			const blob = await getMedia(item.mediaKey);
			if (blob) return await blobToDataUrl(blob);
		}
		if (item.src) {
			const res = await fetch(item.src);
			if (res.ok) return await blobToDataUrl(await res.blob());
		}
	} catch {}
	return "";
}
async function eventPhotoDataUrls(state, eventId) {
	const event = state.events.find((e) => e.id === eventId);
	const items = (state.gallery ?? []).filter((g) => g.eventId === eventId || event && g.eventName && g.eventName === event.name || event && g.caption && g.caption.toLowerCase().includes(event.name.toLowerCase()));
	const urls = [];
	for (const item of items.slice(0, 16)) {
		const src = await gallerySrc(item);
		if (src) urls.push(src);
	}
	return urls;
}
