function buildPressNote(state, eventId) {
	const event = state.events.find((e) => e.id === eventId);
	if (!event) return null;
	const present = [...presentVolunteers(state, eventId)].sort(byFullName);
	const absentCount = state.attendance.filter((a) => a.eventId === eventId).filter((a) => !a.present).length;
	const photoCount = (state.gallery ?? []).filter((g) => g.eventId === event.id || g.eventName && g.eventName === event.name).length;
	const college = state.settings.collegeName;
	const intro = [
		`The NSS unit of ${college} organised “${event.name}” on ${formatLongDate(event.date)} at ${event.location}.`,
		event.description || "",
		`Volunteers present: ${present.length}. Marked absent: ${absentCount}. Service hours credited per volunteer: ${event.hours}. Photographs on file: ${photoCount}.`,
		`Programme Officer: ${state.settings.poName}`
	].filter(Boolean);
	const headers = [
		"Sr. No.",
		"Volunteer ID",
		"Name",
		"Mobile",
		"Unit",
		"Course"
	];
	const rows = present.map((v, i) => [
		String(i + 1),
		v.volunteerId,
		v.fullName,
		v.mobile,
		v.unit,
		`${v.course} · Sem ${v.semester}`
	]);
	const text = [
		"NSS PRESS NOTE",
		college,
		"",
		event.name,
		`Date: ${formatLongDate(event.date)}`,
		`Place: ${event.location}`,
		"",
		...intro
	].join("\n");
	return {
		event,
		intro,
		headers,
		rows,
		presentCount: present.length,
		absentCount,
		photoCount,
		text
	};
}
async function printPressNote(state, eventId) {
	const note = buildPressNote(state, eventId);
	if (!note) return;
	const photos = await eventPhotoDataUrls(state, eventId);
	await printOfficialReport({
		title: `Press Report — ${note.event.name}`,
		headers: note.headers,
		rows: note.rows,
		intro: note.intro,
		photos
	});
}
